<?php
require 'config/database.php';require 'includes/functions.php';$pageTitle='Gestión de miembros';
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['miembro_id']??0);$nombre=trim($_POST['nombre']??'');$apellido=trim($_POST['apellido']??'');$email=trim($_POST['email']??'');$fecha=$_POST['fecha_suscripcion']??date('Y-m-d');
if(!$nombre||!$apellido||!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('Complete los campos y escriba un correo válido.','error');redirect('miembros.php');}
try{if($id){$s=$pdo->prepare("UPDATE miembros SET nombre=?,apellido=?,email=?,fecha_suscripcion=? WHERE miembro_id=?");$s->execute([$nombre,$apellido,$email,$fecha,$id]);flash('Miembro actualizado.');}else{$s=$pdo->prepare("INSERT INTO miembros(nombre,apellido,email,fecha_suscripcion) VALUES(?,?,?,?)");$s->execute([$nombre,$apellido,$email,$fecha]);flash('Miembro registrado.');}}catch(PDOException $e){flash('El correo ya está registrado o los datos no son válidos.','error');}redirect('miembros.php');}
if(isset($_GET['eliminar'])){try{$s=$pdo->prepare("DELETE FROM miembros WHERE miembro_id=?");$s->execute([(int)$_GET['eliminar']]);flash('Miembro eliminado.');}catch(PDOException $e){flash('No se puede eliminar: el miembro tiene préstamos asociados.','error');}redirect('miembros.php');}
$edit=null;if(isset($_GET['editar'])){$s=$pdo->prepare("SELECT * FROM miembros WHERE miembro_id=?");$s->execute([(int)$_GET['editar']]);$edit=$s->fetch();}
$q=trim($_GET['q']??'');$s=$pdo->prepare("SELECT * FROM miembros WHERE nombre LIKE ? OR apellido LIKE ? OR email LIKE ? ORDER BY miembro_id DESC");$like="%$q%";$s->execute([$like,$like,$like]);$rows=$s->fetchAll();require 'includes/header.php';?>
<div class="section-head"><div><h3>Directorio de miembros</h3><p>Administra las personas registradas en la biblioteca.</p></div><span class="count-pill"><?=count($rows)?> miembros</span></div>
<div class="panel form-panel"><h3><?=$edit?'Editar miembro':'Registrar nuevo miembro'?></h3><form method="post" class="form-grid"><input type="hidden" name="miembro_id" value="<?=e($edit['miembro_id']??'')?>"><label>Nombre<input required name="nombre" value="<?=e($edit['nombre']??'')?>" placeholder="Nombres"></label><label>Apellido<input required name="apellido" value="<?=e($edit['apellido']??'')?>" placeholder="Apellidos"></label><label>Correo electrónico<input required type="email" name="email" value="<?=e($edit['email']??'')?>" placeholder="correo@ejemplo.com"></label><label>Fecha de suscripción<input required type="date" name="fecha_suscripcion" value="<?=e($edit['fecha_suscripcion']??date('Y-m-d'))?>"></label><div class="form-actions"><button class="btn primary"><?=$edit?'Guardar cambios':'＋ Registrar miembro'?></button><?php if($edit):?><a class="btn secondary" href="miembros.php">Cancelar</a><?php endif;?></div></form></div>
<form class="searchbar"><input name="q" value="<?=e($q)?>" placeholder="Buscar por nombre, apellido o correo..."><button class="btn secondary">Buscar</button><?php if($q):?><a class="btn ghost" href="miembros.php">Limpiar</a><?php endif;?></form>
<div class="table-wrap"><table><thead><tr><th>ID</th><th>Nombre completo</th><th>Correo</th><th>Suscripción</th><th>Acciones</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty">No se encontraron miembros.</td></tr><?php endif;foreach($rows as $r):?><tr><td>#<?=e($r['miembro_id'])?></td><td><b><?=e($r['nombre'].' '.$r['apellido'])?></b></td><td><?=e($r['email'])?></td><td><?=e($r['fecha_suscripcion'])?></td><td class="actions"><a href="?editar=<?=$r['miembro_id']?>">Editar</a><a class="danger-link" data-confirm="¿Eliminar este miembro?" href="?eliminar=<?=$r['miembro_id']?>">Eliminar</a></td></tr><?php endforeach;?></tbody></table></div><?php require 'includes/footer.php';?>